mapper.select:
/* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.selectResrcePagingList(자원목록조회) */ SELECT T1.* FROM ( SELECT T11.SRVC_YR AS SRVC_YR -- 서비스년도 , T11.RESRCE_NO AS RESRCE_NO -- 자원번호 , T11.PVSN_RESRCE_NM AS PVSN_RESRCE_NM -- 제공자원명 , T11.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO -- 서비스실행사업번호 , T11.GR_TRGT_SRVC_YN AS GR_TRGT_SRVC_YN -- 집단대상서비스여부 , T11.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T11.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD -- 자원제공서비스대분류구분코드 , T11.SRVC_RESRCE_MLSFC_SE_CD AS SRVC_RESRCE_MLSFC_SE_CD -- 자원제공서비스중분류구분코드 , T11.SRVC_RESRCE_SCLAS_SE_CD AS SRVC_RESRCE_SCLAS_SE_CD -- 자원제공서비스소분류구분코드 , T11.SRVC_RESRCE_DTL_SE_CD AS SRVC_RESRCE_DTL_SE_CD -- 자원제공서비스상세구분코드 , T11.RESRCE_RGN_SGG_CD AS RESRCE_RGN_SGG_CD -- 자원지역시군구코드 , T11.RESRCE_SE_CD AS RESRCE_SE_CD -- 자원구분코드 , T11.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , T11.RSFR_INST_NM AS RSFR_INST_NM -- 자원제공주체명 , T11.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 자원제공주체단위업무 , T11.OTM_YN AS OTM_YN -- 일회성여부 , T11.PVSN_BGNG_YMD AS PVSN_BGNG_YMD -- 제공시작일자 , T11.PVSN_END_YMD AS PVSN_END_YMD -- 제공종료일자 , T11.HPGE_URL_ADDR AS HPGE_URL_ADDR -- 홈페이지URL주소 , T11.SRVC_DSCRP_CN AS SRVC_DSCRP_CN -- 서비스설명내용 , T11.USE_YN AS USE_YN -- 사용여부 , T11.PVSN_QY_CNT AS PVSN_QY_CNT -- 제공수량수 , T11.PVSN_AMT AS PVSN_AMT -- 제공금액 , T11.SPRT_CONT AS SPRT_CONT -- 지원횟수 , T11.RSFR_SRVC_SPRT_UNT_SE_CD AS RSFR_SRVC_SPRT_UNT_SE_CD -- 자원제공서비스지원단위구분코드 , T11.SPNGDS_CL_SE_CD AS SPNGDS_CL_SE_CD -- 후원품분류구분코드 , T11.RSFR_CYCL_SE_CD AS RSFR_CYCL_SE_CD -- 자원제공주기구분코드 , T11.VLTWRK_DAYCNT AS VLTWRK_DAYCNT -- 자원봉사일수 , T11.UTZTN_PSNCPA_NOPE AS UTZTN_PSNCPA_NOPE -- 이용정원인원수 , T11.PTCPTN_NOPE AS PTCPTN_NOPE -- 참여인원수 , C##RG.DEC_B64(T11.DPSITR_NM_ENCPT) AS DPSITR_NM -- 기탁자명암호화 , T11.DPSITR_TELNO AS DPSITR_TELNO -- 기탁자전화번호암호화 , T11.DPSTN_UNT_UNTPC_AMT AS DPSTN_UNT_UNTPC_AMT -- 기탁단위단가금액 , T11.ME_ALOTM_AMT AS ME_ALOTM_AMT -- 본인부담금금액 , T11.DPSITR_ANYM_YN AS DPSITR_ANYM_YN -- 기탁자익명여부 , T11.CHG_DMND_DT AS CHG_DMND_DT -- 변경요청일시 , T11.CHG_DMND_ID AS CHG_DMND_ID -- 변경요청아이디 , T11.CHG_DMND_CS_CN AS CHG_DMND_CS_CN -- 변경요청사유내용 , T11.APRV_DT AS APRV_DT -- 승인일시 , T11.APRV_STTS_SE_CD AS APRV_STTS_SE_CD -- 승인상태구분코드 , T11.AUTZR_NO AS AUTZR_NO -- 승인자번호 , C##RG.DEC_B64(T11.AUTZR_NM_ENCPT) AS AUTZR_NM -- 승인자명암호화 , T11.APRV_CN AS APRV_CN -- 승인내용 , T11.RJCT_CS_CN AS RJCT_CS_CN -- 반려사유내용 , T11.ATFINO AS ATFINO -- 첨부파일번호 , T11.OPER_SHAPE_SE_CD AS OPER_SHAPE_SE_CD -- 운영형태구분코드 , T11.ASIS_RESRCE_NO AS ASIS_RESRCE_NO -- ASIS자원번호 , T11.FRST_RGTR_ID AS FRST_RGTR_ID -- 최초등록자아이디 , T11.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시 , T11.LAST_MDFR_ID AS LAST_MDFR_ID -- 최종수정자아이디 , T11.LAST_MDFCN_DT AS LAST_MDFCN_DT -- 최종수정일시 , C##RG.DEC_B64(T11.PIC_NM) AS PIC_NM -- 주강사명암호화 , T11.PIC_UP_INST_NO AS PIC_UP_INST_NO -- 상위기관번호 , T11.PIC_INST_NO AS PIC_INST_NO , T11.RGTR_INST_NM AS RGTR_INST_NM , ROWNUM AS SEQ , C##RG.DEC_B64(T11.PIC_NM_ENCPT) AS PIC_NM FROM ( SELECT /* 자원기본 내역 */ CASE WHEN LENGTH(T21.PVSN_BGNG_YMD) != 8 THEN NULL ELSE SUBSTR(T21.PVSN_BGNG_YMD,1,4) END AS SRVC_YR -- 서비스년도 , T21.RESRCE_NO AS RESRCE_NO -- 자원번호 , T21.PVSN_RESRCE_NM AS PVSN_RESRCE_NM -- 제공자원명 , T21.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO -- 서비스실행사업번호 , T21.GR_TRGT_SRVC_YN AS GR_TRGT_SRVC_YN -- 집단대상서비스여부 , T21.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T21.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD -- 자원제공서비스대분류구분코드 , T21.SRVC_RESRCE_MLSFC_SE_CD AS SRVC_RESRCE_MLSFC_SE_CD -- 자원제공서비스중분류구분코드 , T21.SRVC_RESRCE_SCLAS_SE_CD AS SRVC_RESRCE_SCLAS_SE_CD -- 자원제공서비스소분류구분코드 , T21.SRVC_RESRCE_DTL_SE_CD AS SRVC_RESRCE_DTL_SE_CD -- 자원제공서비스상세구분코드 , T21.RESRCE_RGN_SGG_CD AS RESRCE_RGN_SGG_CD -- 자원지역시군구코드 , T21.RESRCE_SE_CD AS RESRCE_SE_CD -- 자원구분코드 , T21.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , NVL(( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T21.RSFR_INST_NO AND ROWNUM = 1 ), (SELECT X.INST_NM FROM SDA600 X WHERE X.INST_NO = T21.RSFR_INST_NO AND ROWNUM = 1 )) AS RSFR_INST_NM -- 자원제공주체명 , NVL(( SELECT X.UNT_TASKWK_SE_CD FROM SAA000 X WHERE X.INST_NO = T21.RSFR_INST_NO AND ROWNUM = 1 ), (SELECT X.UNT_TASKWK_SE_CD FROM SDA600 X WHERE X.INST_NO = T21.RSFR_INST_NO AND ROWNUM = 1 )) AS UNT_TASKWK_SE_CD -- 단위업무 , T21.OTM_YN AS OTM_YN -- 일회성여부 , T21.PVSN_BGNG_YMD AS PVSN_BGNG_YMD -- 제공시작일자 , T21.PVSN_END_YMD AS PVSN_END_YMD -- 제공종료일자 , T21.HPGE_URL_ADDR AS HPGE_URL_ADDR -- 홈페이지URL주소 , T21.SRVC_DSCRP_CN AS SRVC_DSCRP_CN -- 서비스설명내용 , T21.USE_YN AS USE_YN -- 사용여부 , T21.PVSN_QY_CNT AS PVSN_QY_CNT -- 제공수량수 , T21.PVSN_AMT AS PVSN_AMT -- 제공금액 , T21.SPRT_CONT AS SPRT_CONT -- 지원횟수 , T21.RSFR_SRVC_SPRT_UNT_SE_CD AS RSFR_SRVC_SPRT_UNT_SE_CD -- 자원제공서비스지원단위구분코드 , T21.SPNGDS_CL_SE_CD AS SPNGDS_CL_SE_CD -- 후원품분류구분코드 , T21.RSFR_CYCL_SE_CD AS RSFR_CYCL_SE_CD -- 자원제공주기구분코드 , T21.VLTWRK_DAYCNT AS VLTWRK_DAYCNT -- 자원봉사일수 , T21.UTZTN_PSNCPA_NOPE AS UTZTN_PSNCPA_NOPE -- 이용정원인원수 , T21.PTCPTN_NOPE AS PTCPTN_NOPE -- 참여인원수 , T21.DPSITR_NM_ENCPT AS DPSITR_NM_ENCPT -- 기탁자명암호화 , T21.DPSITR_TELNO AS DPSITR_TELNO -- 기탁자전화번호암호화 , T21.DPSTN_UNT_UNTPC_AMT AS DPSTN_UNT_UNTPC_AMT -- 기탁단위단가금액 , T21.ME_ALOTM_AMT AS ME_ALOTM_AMT -- 본인부담금금액 , T21.DPSITR_ANYM_YN AS DPSITR_ANYM_YN -- 기탁자익명여부 , T21.CHG_DMND_DT AS CHG_DMND_DT -- 변경요청일시 , T21.CHG_DMND_ID AS CHG_DMND_ID -- 변경요청아이디 , T21.CHG_DMND_CS_CN AS CHG_DMND_CS_CN -- 변경요청사유내용 , T21.APRV_DT AS APRV_DT -- 승인일시 , T21.APRV_STTS_SE_CD AS APRV_STTS_SE_CD -- 승인상태구분코드 , T21.AUTZR_NO AS AUTZR_NO -- 승인자번호 , ( SELECT X.FLNM_ENCPT FROM SCA100 X WHERE X.ENFSN_NO = T21.AUTZR_NO AND ROWNUM = 1 ) AS AUTZR_NM_ENCPT -- 승인자명암호화 , T21.APRV_CN AS APRV_CN -- 승인내용 , T21.RJCT_CS_CN AS RJCT_CS_CN -- 반려사유내용 , T21.ATFINO AS ATFINO -- 첨부파일번호 , T21.OPER_SHAPE_SE_CD AS OPER_SHAPE_SE_CD -- 운영형태구분코드 , T21.ASIS_RESRCE_NO AS ASIS_RESRCE_NO -- ASIS자원번호 , T21.FRST_RGTR_ID AS FRST_RGTR_ID -- 최초등록자아이디 , T21.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시 , T21.LAST_MDFR_ID AS LAST_MDFR_ID -- 최종수정자아이디 , T21.LAST_MDFCN_DT AS LAST_MDFCN_DT -- 최종수정일시 , (SELECT QQ.FLNM_ENCPT FROM SCA100 QQ WHERE QQ.ENFSN_NO = X.PIC_NO) AS PIC_NM -- 주강사명암호화 , NVL(Y.UP_APRV_INST_NO,Y.UP_INST_NO) AS PIC_UP_INST_NO , X.PIC_INST_NO AS PIC_INST_NO , (SELECT X1.INST_NM FROM SAA000 X1, SCA100 CA , SAA200 XZ WHERE X1.INST_NO = CA.OGDP_INST_NO AND CA.ENFSN_NO = XZ.ENFSN_NO AND XZ.USER_ID = T21.FRST_RGTR_ID AND ROWNUM = 1 ) RGTR_INST_NM , X.PIC_NM_ENCPT FROM SDA100 T21 /* 자원기본 */, SDA110 X /*자원관리담당자*/, SAA000 Y /*통합기관*/ WHERE 1 = 1 AND X.RESRCE_NO = T21.RESRCE_NO AND X.PCHPRS_YN = 'Y' AND X.PIC_INST_NO = Y.INST_NO
) T11 WHERE 1 = 1
ORDER BY T11.PVSN_BGNG_YMD DESC, T11.RESRCE_NO DESC ) T1
WHERE T1.SEQ >= #{START_IDX} AND T1.SEQ <= #{LAST_IDX}

SELECT /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.selectEduSchdlDtlList(교육시간표 상세 목록 조회) */ T11.LCTRE_YMD AS LCTRE_YMD , T11.EDU_PROGRM_SE_CD AS EDU_PROGRM_SE_CD , T11.PROGRM_TTL_NM AS PROGRM_TTL_NM , T11.PROGRM_BGNG_HR AS PROGRM_BGNG_HR , T11.PROGRM_END_HR AS PROGRM_END_HR , T11.PROGRM_DTL_CN AS PROGRM_DTL_CN , T11.LCTRE_HR AS LCTRE_HR , T11.PROGRM_DSCRP_CN AS PROGRM_DSCRP_CN , T11.PROGRM_CN AS PROGRM_CN , T11.PROGRM_BGNG_YMD AS PROGRM_BGNG_YMD , T11.PROGRM_END_YMD AS PROGRM_END_YMD , T11.PROGRM_SUM_HR AS PROGRM_SUM_HR , T11.INSTR_ENFSN_NO AS INSTR_ENFSN_NO , T11.INSTR_ENFSN_NM AS INSTR_ENFSN_NM , T11.PCHPRS_YN AS PCHPRS_YN , T11.BIZ_YR AS BIZ_YR , T11.RESRCE_NO AS RESRCE_NO , T11.INST_NO AS INST_NO , T11.PROGRM_NO AS PROGRM_NO , T11.LCTRE_SN AS LCTRE_SN , T11.APRV_STTS_SE_CD AS APRV_STTS_SE_CD FROM ( SELECT T4.LCTRE_YMD AS LCTRE_YMD /* 강의일자 */ , T2.EDU_PROGRM_SE_CD AS EDU_PROGRM_SE_CD /* 교육프로그램구분코드 */ , T2.PROGRM_TTL_NM AS PROGRM_TTL_NM /* 프로그램제목명 */ , SUBSTR(REPLACE(T3.PROGRM_BGNG_HR, ':', ''),1,2) || ':' || SUBSTR(REPLACE(T3.PROGRM_BGNG_HR, ':', ''),3,2) AS PROGRM_BGNG_HR /* 프로그램시작시간 */ , SUBSTR(REPLACE(T3.PROGRM_END_HR , ':', ''),1,2) || ':' || SUBSTR(REPLACE(T3.PROGRM_END_HR , ':', ''),3,2) AS PROGRM_END_HR /* 프로그램종료시간 */ , T4.PROGRM_DTL_CN AS PROGRM_DTL_CN /* 프로그램상세내용 */ , T4.LCTRE_HR AS LCTRE_HR /* 강의시간 */ , T2.PROGRM_DSCRP_CN AS PROGRM_DSCRP_CN /* 프로그램설명내용 */ , T2.PROGRM_CN AS PROGRM_CN /* 프로그램내용 */ , T2.PROGRM_BGNG_YMD AS PROGRM_BGNG_YMD /* 프로그램시작일자 */ , T2.PROGRM_END_YMD AS PROGRM_END_YMD /* 프로그램종료일자 */ , T2.PROGRM_SUM_HR AS PROGRM_SUM_HR /* 프로그램합계시간 */
, ( SELECT LISTAGG(X.INSTR_ENFSN_NO, ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC) FROM SDA342 X /* 자원프로그램강사 */ WHERE X.PROGRM_NO = T3.PROGRM_NO AND X.RESRCE_NO = T3.RESRCE_NO AND X.LCTRE_SN = T3.LCTRE_SN AND X.DEL_YN = 'N' GROUP BY X.PROGRM_NO , X.RESRCE_NO , X.LCTRE_SN ) AS INSTR_ENFSN_NO /* 강사종사자번호 */ , ( SELECT LISTAGG(C##RG.DEC_B64(Y.FLNM_ENCPT), ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC) FROM SDA342 X /* 자원프로그램강사 */ , SCA100 Y /* 종사자 */ WHERE X.PROGRM_NO = T3.PROGRM_NO AND X.RESRCE_NO = T3.RESRCE_NO AND X.LCTRE_SN = T3.LCTRE_SN AND X.DEL_YN = 'N' AND X.INSTR_ENFSN_NO = Y.ENFSN_NO GROUP BY X.PROGRM_NO , X.RESRCE_NO , X.LCTRE_SN ) AS INSTR_ENFSN_NM /* 강사종사자명 */ , ( SELECT LISTAGG(X.PCHPRS_YN, ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC) FROM SDA342 X /* 자원프로그램강사 */ WHERE X.PROGRM_NO = T3.PROGRM_NO AND X.RESRCE_NO = T3.RESRCE_NO AND X.LCTRE_SN = T3.LCTRE_SN AND X.DEL_YN = 'N' GROUP BY X.PROGRM_NO , X.RESRCE_NO , X.LCTRE_SN ) AS PCHPRS_YN /* 주담당자여부 */
, ( SELECT X.BIZ_YR /* 사업년도 */ FROM SDA400 X /* 서비스사업 */ , SDA420 Y /* 서비스실행사업 */ WHERE X.SRVC_BIZ_NO = Y. SRVC_BIZ_NO AND Y.SRVC_EXCN_BIZ_NO = T1.SRVC_EXCN_BIZ_NO ) AS BIZ_YR /* 사업년도 */
, T1.RESRCE_NO AS RESRCE_NO , T1.RSFR_INST_NO AS INST_NO , T2.PROGRM_NO AS PROGRM_NO , T3.LCTRE_SN AS LCTRE_SN , T1.APRV_STTS_SE_CD AS APRV_STTS_SE_CD FROM SDA100 T1 /* 자원기본 */ , SDA300 T2 /* 자원프로그램 */ , SDA340 T3 /* 자원프로그램상세일정 */ , SDA320 T4 /* 자원프로그램실행시간 */ WHERE T1.RESRCE_NO = T2.RESRCE_NO /* 자원번호 */ AND T2.PROGRM_NO = T3.PROGRM_NO /* 프로그램번호 */ AND T2.RESRCE_NO = T3.RESRCE_NO /* 자원번호 */ AND T3.PROGRM_NO = T4.PROGRM_NO /* 프로그램번호 */ AND T3.RESRCE_NO = T4.RESRCE_NO /* 자원번호 */ AND T3.LCTRE_SN = T4.LCTRE_SN /* 강의일련번호 */ AND T1.USE_YN = 'Y' AND T2.DEL_YN = 'N' AND T3.DEL_YN = 'N' ORDER BY T1.RESRCE_NO , T4.LCTRE_YMD , T2.EDU_PROGRM_SE_CD , T2.PROGRM_TTL_NM , T2.PROGRM_NO ) T11 WHERE 1 = 1
AND T11.LCTRE_YMD LIKE #{BIZ_YR} || '%'
AND T11.LCTRE_YMD LIKE '____' || #{MM} || '__'
AND T11.INST_NO = #{INST_NO}
AND T11.RESRCE_NO = #{RESRCE_NO}
AND T11.EDU_PROGRM_SE_CD = #{EDU_PROGRM_SE_CD}
ORDER BY LCTRE_YMD, PROGRM_BGNG_HR

SELECT /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.selectEduHrDt(교육시간표 조회) */ T11.PROGRM_YMD , T11.EDU_PROGRM_SE_CD , T11.PROGRM_NM , T11.HR , T11.LCTRE_HR , T11.PROGRM_DTL_CN , T11.INSTR_ENFSN_NO , T11.RESRCE_NO , T11.INST_NO , T11.BIZ_YR , T11.FLNM_ENCPT FROM ( SELECT T1.PROGRM_YMD AS PROGRM_YMD /* 작업일자 */ , T1.EDU_PROGRM_SE_CD AS EDU_PROGRM_SE_CD /* 교육프로그램구분코드 */ , T1.PROGRM_NM AS PROGRM_NM /* 교육과목 */ --, T1.PROGRM_BGNG_HR || '~' || T1.PROGRM_END_HR AS HR /* 교육시간 */ , SUBSTR(T1.PROGRM_BGNG_HR,0,2) || ':' || SUBSTR(T1.PROGRM_BGNG_HR,3,2) || '~' || SUBSTR(T1.PROGRM_END_HR,0,2) || ':' || SUBSTR(T1.PROGRM_END_HR,3,2) AS HR /* 교육시간 */ , T1.LCTRE_HR AS LCTRE_HR /* 교육시간수 */ , T1.PROGRM_DTL_CN AS PROGRM_DTL_CN /* 교육내용 */ , T2.INSTR_ENFSN_NO AS INSTR_ENFSN_NO /* 강사번호 */ , T1.RESRCE_NO AS RESRCE_NO /* 자원번호 */ , T1.INST_NO AS INST_NO /* 기관번호 */ , ( SELECT X.BIZ_YR /* 사업년도 */ FROM SDA400 X /* 서비스사업 */ , SDA420 Y /* 서비스실행사업 */ , SDA100 Z WHERE X.SRVC_BIZ_NO = Y.SRVC_BIZ_NO AND Y.SRVC_EXCN_BIZ_NO = Z.SRVC_EXCN_BIZ_NO AND Z.RESRCE_NO = T1.RESRCE_NO ) AS BIZ_YR /* 사업년도 */ , ( SELECT C##RG.DEC_B64(X.FLNM_ENCPT) FROM SCA100 X WHERE X.ENFSN_NO = T2.INSTR_ENFSN_NO ) AS FLNM_ENCPT FROM SDA510 T1 ,SDA511 T2 WHERE T1.JOB_YMD = T2.JOB_YMD AND T1.OPRTR_ID = T2.OPRTR_ID AND T1.TMPR_SN = T2.TMPR_SN ) T11 WHERE 1 = 1
AND T11.PROGRM_YMD LIKE #{BIZ_YR} || '%'
AND T11.PROGRM_YMD LIKE '____' || #{MM} || '__'
AND T11.INST_NO = #{INST_NO}
AND T11.RESRCE_NO = #{RESRCE_NO}
AND T11.EDU_PROGRM_SE_CD = #{EDU_PROGRM_SE_CD}
ORDER BY PROGRM_YMD, HR

/* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.selectProgrmNo(프로그램번호 가져오기) */
SELECT PROGRM_NO AS PROGRM_NO
  FROM SDA300 /* 자원프로그램 */
WHERE 1=1
  AND RESRCE_NO     = #{RESRCE_NO} -- 자원번호
  AND PROGRM_TTL_NM = #{PROGRM_TTL_NM}
  AND DEL_YN        = 'N'
  AND EDU_PROGRM_SE_CD = #{EDU_PROGRM_SE_CD}

mapper.insert:
/* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.insertExcvHr(자원프로그램실행시간등록) */
INSERT INTO SDA320
  (PROGRM_NO
  , RESRCE_NO
  , LCTRE_SN
  , LCTRE_YMD
  , LCTRE_HR
  , PROGRM_DTL_CN
  , FRST_RGTR_ID
  , FRST_REG_DT
  , LAST_MDFR_ID
  , LAST_MDFCN_DT)
VALUES
  (#{PROGRM_NO}
  , #{RESRCE_NO}
  , #{LCTRE_SN}
  , #{LCTRE_YMD}
  , #{LCTRE_HR}
  , #{PROGRM_DTL_CN}
  , #{SESS_USER_ID}
  , SYSDATE
  , #{SESS_USER_ID}
  , SYSDATE)


SELECT NVL(MAX(TMPR_SN),0)+1 AS TMPR_SN FROM SDA510 WHERE JOB_YMD = #{JOB_YMD} AND OPRTR_ID = #{OPRTR_ID}

     /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.insertEduHrDtlRegExcelUpload(교육시간표상세 일괄등록 엑셀업로드) */

      INSERT INTO SDA510 /* 엑셀업로드수업일정 */
        (JOB_YMD
        , OPRTR_ID
        , TMPR_SN
        , INST_NO
        , RESRCE_NO
        , PROGRM_YMD
        , PROGRM_NM
        , EDU_PROGRM_SE_CD
        , PROGRM_BGNG_HR
        , PROGRM_END_HR
        , LCTRE_HR
        , PROGRM_DTL_CN
        , FRST_RGTR_ID
        , FRST_REG_DT
        , LAST_MDFR_ID
        , LAST_MDFCN_DT)
      VALUES
        (#{JOB_YMD}
        , #{OPRTR_ID}
        , #{TMPR_SN}
        , #{INST_NO}
        , #{RESRCE_NO}
        , #{PROGRM_YMD}
        , #{PROGRM_NM}
        , #{EDU_PROGRM_SE_CD}
        , #{PROGRM_BGNG_HR}
        , #{PROGRM_END_HR}
        , #{LCTRE_HR}
        , #{PROGRM_DTL_CN}
        , #{FRST_RGTR_ID}
        , SYSDATE
        , #{LAST_MDFR_ID}
        , SYSDATE)


SELECT TMPR_SN FROM SDA510
WHERE   RESRCE_NO           = #{RESRCE_NO}
    AND PROGRM_YMD          = #{PROGRM_YMD}
    AND PROGRM_NM           = #{PROGRM_NM}
    AND EDU_PROGRM_SE_CD    = #{EDU_PROGRM_SE_CD}
    AND PROGRM_BGNG_HR      = #{PROGRM_BGNG_HR}
    AND PROGRM_END_HR       = #{PROGRM_END_HR}

     /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.insertEduHrDtlRegInStrExcelUpload(교육시간표상세 일괄등록 엑셀업로드_강사) */

      INSERT INTO SDA511 /* 엑셀업로드강사 */
        (JOB_YMD
        , OPRTR_ID
        , TMPR_SN
        , INSTR_ENFSN_NO
        , COMPNO_INSTR_YN
        , PCHPRS_YN
        , FRST_RGTR_ID
        , FRST_REG_DT
        , LAST_MDFR_ID
        , LAST_MDFCN_DT)
        VALUES
        (#{JOB_YMD}
        , #{OPRTR_ID}
        , #{TMPR_SN}
        , #{INSTR_ENFSN_NO}
        , NVL(#{COMPNO_INSTR_YN},'N')
        , NVL(#{PCHPRS_YN},'N')
        , #{FRST_RGTR_ID}
        , SYSDATE
        , #{LAST_MDFR_ID}
        , SYSDATE)

mapper.delete:
DELETE /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.deleteAllDel(교육시간표상세 일괄등록 전체삭제) */
  FROM SDA510 T1    /* 엑셀업로드수업일정 */
WHERE   JOB_YMD     = #{JOB_YMD}
    AND OPRTR_ID    = #{OPRTR_ID}
    AND TMPR_SN     = #{TMPR_SN}

DELETE /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.deleteInStrAllDel(교육시간표상세 일괄등록 전체삭제_강사) */
  FROM SDA511 T1    /* 엑셀업로드강사 */
WHERE   JOB_YMD     = #{JOB_YMD}
    AND OPRTR_ID    = #{OPRTR_ID}
    AND TMPR_SN     = #{TMPR_SN}

mapper.update:
        /* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.updateExcvHr(자원프로그램실행시간 수정) */
        UPDATE SDA320 /* 자원프로그램실행시간 */
		 SET LCTRE_HR       = #{LCTRE_HR}
		   , PROGRM_DTL_CN  = #{PROGRM_DTL_CN}
		   , LAST_MDFR_ID   = #{LAST_MDFR_ID}
		   , LAST_MDFCN_DT  = SYSDATE
		 WHERE PROGRM_NO    = #{PROGRM_NO}
		  AND RESRCE_NO     = #{RESRCE_NO}
		  AND LCTRE_SN      = #{LCTRE_SN}
		  AND LCTRE_YMD     = #{LCTRE_YMD}

/* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.updateLcreHr(자원프로그램실행시간 강의시간 수정) */
UPDATE SDA320 /* 자원프로그램실행시간 */
 SET LCTRE_HR       = '0'
   , LAST_MDFR_ID   = #{LAST_MDFR_ID}
   , LAST_MDFCN_DT  = SYSDATE
 WHERE PROGRM_NO    = #{PROGRM_NO}
  AND RESRCE_NO     = #{RESRCE_NO}
  AND LCTRE_SN      = #{LCTRE_SN}
  AND LCTRE_YMD     = #{LCTRE_YMD}

mapper.select:
/* isry.itgcm.crtrinfo.resrce.SrvcResrceMapper.selectLctreSn(강의일련번호 320) */
SELECT
    LCTRE_SN AS LCTRE_SN
FROM SDA340
WHERE PROGRM_NO         = #{PROGRM_NO}
 AND RESRCE_NO          = #{RESRCE_NO}  -- 자원번호
 AND LCTRE_BGNG_YMD     = #{LCTRE_BGNG_YMD}

SELECT T1.ENFSN_NO AS INSTR_ENFSN_NO , C##RG.DEC_B64(T1.FLNM_ENCPT) AS FLNM_ENCPT , T1.OGDP_INST_NO AS INST_NO , (SELECT X.INST_NM FROM SAA000 X /* 통합기관 */ WHERE X.INST_NO = T1.OGDP_INST_NO ) AS INST_NM FROM SCA100 T1 , SAA200 T2 , SCA300 T3 WHERE T1.ENFSN_NO = T2.ENFSN_NO(+) AND T1.INDV_IDNTFC_NO = T3.INDV_IDNTFC_NO(+)
AND T1.FLNM_ENCPT = (C##RG.ENC_B64(#{FLNM_ENCPT}))
AND T1.OGDP_INST_NO = #{INST_NO}
